from __future__ import annotations

from dataclasses import dataclass
from hashlib import sha256
from pathlib import Path
from typing import Any, Iterable, List, Optional, Protocol, Tuple
import json
import logging
import secrets
import time

# Module-level constants
LOGGER = logging.getLogger(__name__)
METADATA_ENCODING = "utf-8"
FILENAME_PREFIX = "entry-"
DATA_SUFFIX = ".bin"
METADATA_SUFFIX = ".meta.json"


class CacheError(Exception):
    """Base exception for all cache-related errors."""


class CacheKeyNotFoundError(CacheError, KeyError):
    """Raised when a requested key is not present in the cache."""


class CacheCorruptionError(CacheError):
    """Raised when on-disk state is inconsistent or corrupted."""


class CacheCapacityError(CacheError):
    """Raised when the cache cannot store an entry due to capacity limits."""


class ValueSerialiser(Protocol):
    """Protocol for value serialisers used by the cache."""

    def serialise(self, value: Any) -> bytes:
        """Serialise a Python value to bytes suitable for on-disk storage."""

    def deserialise(self, data: bytes) -> Any:
        """Deserialise bytes from disk into a Python value."""


class JsonSerialiser:
    """JSON serialiser for values that are JSON-serialisable."""

    def serialise(self, value: Any) -> bytes:
        """Serialise a Python value to UTF-8 encoded JSON bytes."""
        try:
            text = json.dumps(value, separators=(",", ":"), ensure_ascii=False)
            return text.encode(METADATA_ENCODING)
        except (TypeError, ValueError) as exc:
            raise CacheError("Value is not JSON-serialisable") from exc

    def deserialise(self, data: bytes) -> Any:
        """Deserialise UTF-8 encoded JSON bytes into a Python value."""
        try:
            return json.loads(data.decode(METADATA_ENCODING))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise CacheCorruptionError("Stored JSON value could not be decoded") from exc


class BytesPassthroughSerialiser:
    """Identity serialiser for bytes values."""

    def serialise(self, value: Any) -> bytes:
        """Return bytes unchanged; raise if value is not bytes."""
        if isinstance(value, (bytes, bytearray, memoryview)):
            return bytes(value)
        raise CacheError("BytesPassthroughSerialiser only accepts bytes-like values")

    def deserialise(self, data: bytes) -> Any:
        """Return bytes unchanged."""
        return data


@dataclass(frozen=True)
class EntryMetadata:
    """Immutable metadata for a cache entry.

    Times are stored as UNIX epoch seconds for portability.
    """

    key: str
    created_at: float
    last_access_at: float
    size_bytes: int
    expires_at: Optional[float]  # None means no expiry

    def to_mapping(self) -> dict:
        """Convert to a plain mapping suitable for JSON encoding."""
        return {
            "key": self.key,
            "created_at": self.created_at,
            "last_access_at": self.last_access_at,
            "size_bytes": self.size_bytes,
            "expires_at": self.expires_at,
        }

    @staticmethod
    def from_mapping(mapping: dict) -> "EntryMetadata":
        """Create metadata from a plain mapping."""
        required = ("key", "created_at", "last_access_at", "size_bytes", "expires_at")
        missing = [name for name in required if name not in mapping]
        if missing:
            raise CacheCorruptionError(f"Metadata missing fields: {missing}")
        return EntryMetadata(
            key=str(mapping["key"]),
            created_at=float(mapping["created_at"]),
            last_access_at=float(mapping["last_access_at"]),
            size_bytes=int(mapping["size_bytes"]),
            expires_at=None if mapping["expires_at"] is None else float(mapping["expires_at"]),
        )


class DiskCache:
    """A small on-disk key/value cache.

    - Keys are str; values are serialised to bytes using a pluggable serialiser.
    - Entries are stored as one data file and one metadata file per key.
    - Expired entries are removed upon access and during pruning.
    - Atomic writes are achieved by writing to a temporary file and replacing the target.
    - For simplicity and predictable behaviour, this cache linearly scans metadata files
      when pruning. This is acceptable for small caches and avoids complicated in-memory
      indexes. This algorithmic choice trades raw performance for robustness and clarity.

    Notes on British English: docstrings and comments use British spelling such as
    initialise, behaviour, and colour.
    """

    def __init__(
        self,
        cache_directory: Path,
        default_time_to_live: Optional[float] = None,
        maximum_entries: Optional[int] = None,
        maximum_bytes: Optional[int] = None,
        value_serialiser: Optional[ValueSerialiser] = None,
    ) -> None:
        """Initialise the disk cache.

        Parameters:
            cache_directory: Directory where cache files are stored. Will be created.
            default_time_to_live: Default time-to-live in seconds for new entries.
            maximum_entries: Maximum number of entries; oldest are evicted when exceeded.
            maximum_bytes: Maximum total bytes; least recently used are evicted when exceeded.
            value_serialiser: Strategy used to serialise values; JSON by default.
        """
        self._directory = Path(cache_directory)
        self._default_time_to_live = default_time_to_live
        self._maximum_entries = maximum_entries
        self._maximum_bytes = maximum_bytes
        self._value_serialiser = value_serialiser or JsonSerialiser()

        self._ensure_directory()

    def set(self, key: str, value: Any, time_to_live: Optional[float] = None) -> None:
        """Store a value under a key. Overwrites any existing value.

        Parameters:
            key: Cache key (must be a str).
            value: The value to store.
            time_to_live: Optional per-entry time-to-live in seconds.
        """
        self._validate_key(key)
        now = self._now()
        expires_at = self._resolve_expiry(now, time_to_live)
        data = self._value_serialiser.serialise(value)

        hashed = self._hash_key(key)
        data_path, meta_path = self._entry_paths(hashed)
        metadata = EntryMetadata(
            key=key,
            created_at=now,
            last_access_at=now,
            size_bytes=len(data),
            expires_at=expires_at,
        )

        self._write_atomic_bytes(data_path, data)
        self._write_atomic_text(meta_path, json.dumps(metadata.to_mapping(), ensure_ascii=False), METADATA_ENCODING)

        try:
            self.prune()
        except CacheError:
            # Pruning failure should not hide a successful set; log and continue.
            LOGGER.warning("Pruning failed after setting key '%s'", key, exc_info=True)

    def get(self, key: str) -> Any:
        """Retrieve a value by key or raise CacheKeyNotFoundError if missing or expired."""
        self._validate_key(key)
        hashed = self._hash_key(key)
        data_path, meta_path = self._entry_paths(hashed)

        metadata = self._load_metadata(meta_path)
        if metadata.key != key:
            # Hash collision or tampering; remove to self-heal.
            self._safe_remove_pair(data_path, meta_path)
            raise CacheCorruptionError("Key mismatch detected between hash and stored metadata")

        if self._is_expired(metadata, self._now()):
            self._safe_remove_pair(data_path, meta_path)
            raise CacheKeyNotFoundError(key)

        data = self._read_bytes(data_path)
        value = self._value_serialiser.deserialise(data)
        self._touch_metadata(meta_path, metadata)
        return value

    def has_key(self, key: str) -> bool:
        """Return True if a non-expired entry exists for key, False otherwise."""
        self._validate_key(key)
        hashed = self._hash_key(key)
        _, meta_path = self._entry_paths(hashed)

        try:
            metadata = self._load_metadata(meta_path)
        except CacheCorruptionError:
            # Self-heal by removing corrupt artifacts.
            self._safe_remove_path(meta_path)
            return False

        if metadata.key != key or self._is_expired(metadata, self._now()):
            self.delete(key)
            return False
        return True

    def delete(self, key: str) -> None:
        """Delete a key if present. It is not an error if the key does not exist."""
        self._validate_key(key)
        hashed = self._hash_key(key)
        data_path, meta_path = self._entry_paths(hashed)
        self._safe_remove_path(data_path)
        self._safe_remove_path(meta_path)

    def clear(self) -> None:
        """Remove all cache entries in the directory managed by this cache."""
        for path in self._directory.glob(f"{FILENAME_PREFIX}*{DATA_SUFFIX}"):
            self._safe_remove_path(path)
        for path in self._directory.glob(f"{FILENAME_PREFIX}*{METADATA_SUFFIX}"):
            self._safe_remove_path(path)

    def keys(self) -> Iterable[str]:
        """Yield all non-expired keys currently present in the cache."""
        now = self._now()
        for meta_path in self._directory.glob(f"{FILENAME_PREFIX}*{METADATA_SUFFIX}"):
            try:
                metadata = self._load_metadata(meta_path)
            except CacheCorruptionError:
                self._safe_remove_path(meta_path)
                continue
            if self._is_expired(metadata, now):
                hashed = meta_path.stem[len(FILENAME_PREFIX) :]
                self._safe_remove_pair(*self._entry_paths(hashed))
                continue
            yield metadata.key

    def prune(self) -> None:
        """Remove expired entries and enforce capacity limits.

        Non-obvious algorithmic choice:
        - We scan all metadata files and perform simple sorts to choose eviction
          candidates. This keeps the implementation small and robust for small caches.
        """
        entries = self._load_all_entries()
        now = self._now()

        # Remove expired entries first.
        for hashed, metadata in entries:
            if self._is_expired(metadata, now):
                self._safe_remove_pair(*self._entry_paths(hashed))
        entries = [(h, m) for (h, m) in entries if not self._is_expired(m, now)]

        if self._maximum_entries is not None:
            self._evict_to_entry_limit(entries, self._maximum_entries)

        if self._maximum_bytes is not None:
            self._evict_to_byte_limit(entries, self._maximum_bytes)

    # Private helpers

    def _ensure_directory(self) -> None:
        """Create the cache directory if it does not exist."""
        if self._directory.exists():
            if not self._directory.is_dir():
                raise CacheError(f"Cache path is not a directory: {self._directory}")
            return
        self._directory.mkdir(parents=True, exist_ok=True)

    def _validate_key(self, key: str) -> None:
        """Validate that key is a non-empty str."""
        if not isinstance(key, str):
            raise TypeError("Key must be a str")
        if key == "":
            raise ValueError("Key must not be empty")

    def _hash_key(self, key: str) -> str:
        """Return a stable hexadecimal hash for the key."""
        digest = sha256(key.encode(METADATA_ENCODING)).hexdigest()
        return digest

    def _entry_paths(self, hashed: str) -> Tuple[Path, Path]:
        """Return (data_path, meta_path) for a hashed key."""
        data_path = self._directory / f"{FILENAME_PREFIX}{hashed}{DATA_SUFFIX}"
        meta_path = self._directory / f"{FILENAME_PREFIX}{hashed}{METADATA_SUFFIX}"
        return data_path, meta_path

    def _now(self) -> float:
        """Return current UNIX epoch seconds."""
        return time.time()

    def _resolve_expiry(self, now: float, time_to_live: Optional[float]) -> Optional[float]:
        """Compute absolute expiry from time-to-live value."""
        ttl = self._default_time_to_live if time_to_live is None else time_to_live
        if ttl is None:
            return None
        if ttl <= 0:
            # Immediate expiry: store with a past timestamp to aid eager cleanup.
            return now - 1.0
        return now + ttl

    def _write_atomic_bytes(self, target: Path, data: bytes) -> None:
        """Atomically write bytes to target path."""
        temp = target.with_suffix(target.suffix + f".tmp-{secrets.token_hex(8)}")
        try:
            with temp.open("wb") as fh:
                fh.write(data)
            temp.replace(target)
        finally:
            if temp.exists():
                self._safe_remove_path(temp)

    def _write_atomic_text(self, target: Path, text: str, encoding: str) -> None:
        """Atomically write text to target path."""
        temp = target.with_suffix(target.suffix + f".tmp-{secrets.token_hex(8)}")
        try:
            with temp.open("w", encoding=encoding, newline="\n") as fh:
                fh.write(text)
            temp.replace(target)
        finally:
            if temp.exists():
                self._safe_remove_path(temp)

    def _read_bytes(self, path: Path) -> bytes:
        """Read bytes from path, raising CacheKeyNotFoundError if not present."""
        try:
            return path.read_bytes()
        except FileNotFoundError as exc:
            raise CacheKeyNotFoundError(f"Missing data file: {path}") from exc

    def _load_metadata(self, meta_path: Path) -> EntryMetadata:
        """Load metadata from a JSON file."""
        try:
            text = meta_path.read_text(encoding=METADATA_ENCODING)
        except FileNotFoundError as exc:
            raise CacheKeyNotFoundError(f"Missing metadata file: {meta_path}") from exc
        try:
            data = json.loads(text)
            return EntryMetadata.from_mapping(data)
        except (json.JSONDecodeError, CacheCorruptionError) as exc:
            raise CacheCorruptionError(f"Invalid metadata in {meta_path}") from exc

    def _touch_metadata(self, meta_path: Path, metadata: EntryMetadata) -> None:
        """Update last_access_at field in metadata."""
        updated = EntryMetadata(
            key=metadata.key,
            created_at=metadata.created_at,
            last_access_at=self._now(),
            size_bytes=metadata.size_bytes,
            expires_at=metadata.expires_at,
        )
        self._write_atomic_text(meta_path, json.dumps(updated.to_mapping(), ensure_ascii=False), METADATA_ENCODING)

    def _is_expired(self, metadata: EntryMetadata, now: float) -> bool:
        """Return True if the entry is expired."""
        if metadata.expires_at is None:
            return False
        return now >= metadata.expires_at

    def _safe_remove_pair(self, data_path: Path, meta_path: Path) -> None:
        """Remove both data and metadata paths, ignoring if not present."""
        self._safe_remove_path(data_path)
        self._safe_remove_path(meta_path)

    def _safe_remove_path(self, path: Path) -> None:
        """Remove a file if present, logging failures."""
        try:
            path.unlink(missing_ok=True)
        except PermissionError:
            LOGGER.warning("Could not remove file due to permission error: %s", path, exc_info=True)

    def _load_all_entries(self) -> List[Tuple[str, EntryMetadata]]:
        """Load all entry metadata from the cache directory."""
        entries: List[Tuple[str, EntryMetadata]] = []
        for meta_path in self._directory.glob(f"{FILENAME_PREFIX}*{METADATA_SUFFIX}"):
            hashed = meta_path.stem[len(FILENAME_PREFIX) :]
            try:
                metadata = self._load_metadata(meta_path)
            except CacheCorruptionError:
                self._safe_remove_path(meta_path)
                continue
            entries.append((hashed, metadata))
        return entries

    def _evict_to_entry_limit(self, entries: List[Tuple[str, EntryMetadata]], limit: int) -> None:
        """Evict least recently used entries until the entry count is within limit."""
        if len(entries) <= limit:
            return
        # Sort by last access time ascending (least recently used first).
        for hashed, _ in sorted(entries, key=lambda item: item[1].last_access_at)[: len(entries) - limit]:
            self._safe_remove_pair(*self._entry_paths(hashed))

    def _evict_to_byte_limit(self, entries: List[Tuple[str, EntryMetadata]], limit_bytes: int) -> None:
        """Evict least recently used entries until total bytes are within limit."""
        # Recompute after potential prior evictions by considering only files that still exist.
        filtered: List[Tuple[str, EntryMetadata]] = []
        total = 0
        for hashed, metadata in entries:
            data_path, meta_path = self._entry_paths(hashed)
            if data_path.exists() and meta_path.exists():
                filtered.append((hashed, metadata))
                total += metadata.size_bytes

        if total <= limit_bytes:
            return

        # Evict in order of least recent access until under the byte limit.
        for hashed, metadata in sorted(filtered, key=lambda item: item[1].last_access_at):
            self._safe_remove_pair(*self._entry_paths(hashed))
            total -= metadata.size_bytes
            if total <= limit_bytes:
                return

    # Convenience constructors

    @classmethod
    def with_json_values(
        cls,
        cache_directory: Path,
        default_time_to_live: Optional[float] = None,
        maximum_entries: Optional[int] = None,
        maximum_bytes: Optional[int] = None,
    ) -> "DiskCache":
        """Create a DiskCache using JSON serialisation for values."""
        return cls(
            cache_directory=cache_directory,
            default_time_to_live=default_time_to_live,
            maximum_entries=maximum_entries,
            maximum_bytes=maximum_bytes,
            value_serialiser=JsonSerialiser(),
        )

    @classmethod
    def with_bytes_values(
        cls,
        cache_directory: Path,
        default_time_to_live: Optional[float] = None,
        maximum_entries: Optional[int] = None,
        maximum_bytes: Optional[int] = None,
    ) -> "DiskCache":
        """Create a DiskCache that stores raw bytes values."""
        return cls(
            cache_directory=cache_directory,
            default_time_to_live=default_time_to_live,
            maximum_entries=maximum_entries,
            maximum_bytes=maximum_bytes,
            value_serialiser=BytesPassthroughSerialiser(),
        )

import hashlib
import json
import logging
import shutil
import time
import uuid
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Optional, Protocol, Tuple

LOGGER = logging.getLogger(__name__)

DATA_SUFFIX = ".bin"
META_SUFFIX = ".meta.json"
DEFAULT_SHARD_DEPTH = 2
DEFAULT_SHARD_WIDTH = 2

# Sentinel for default value handling
_MISSING: object = object()


class CacheError(Exception):
    """Base exception for cache-related errors."""


class CacheKeyError(KeyError):
    """Raised when a cache key is not present or has expired."""


class CacheCorruptionError(CacheError):
    """Raised when on-disk data is corrupt or in an inconsistent state."""


class CacheWriteError(OSError):
    """Raised when the cache fails to write to disk."""


class Serialiser(Protocol):
    """Protocol for serialisation behaviour supplied to DiskCache."""

    def dumps(self, value: Any) -> bytes:
        """Serialise a Python object to bytes."""
        ...

    def loads(self, data: bytes) -> Any:
        """Deserialise bytes back into a Python object."""
        ...


class JSONSerialiser:
    """JSON-based serialiser that operates on bytes."""

    def dumps(self, value: Any) -> bytes:
        """Serialise a JSON-compatible value to UTF-8 encoded bytes."""
        try:
            text = json.dumps(value, separators=(",", ":"), ensure_ascii=False)
        except (TypeError, ValueError) as exc:
            raise ValueError("Value is not JSON-serialisable") from exc
        return text.encode("utf-8")

    def loads(self, data: bytes) -> Any:
        """Deserialise UTF-8 encoded JSON bytes back into a Python value."""
        try:
            return json.loads(data.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise CacheCorruptionError("Stored JSON value is corrupt") from exc


@dataclass(frozen=True)
class CacheSettings:
    """Immutable collection of cache configuration."""

    max_entries: Optional[int] = None
    shard_depth: int = DEFAULT_SHARD_DEPTH
    shard_width: int = DEFAULT_SHARD_WIDTH


class DiskCache:
    """A small on-disk key/value cache with optional expiry and capacity control.

    The cache stores each value as a separate file sharded into subdirectories
    for scalability. A small JSON metadata companion file records timestamps.
    Atomic replace is used to avoid torn writes.

    Non-obvious choice: capacity enforcement uses file modification time as a
    cheap proxy for recency, avoiding reading all metadata for performance.
    """

    def __init__(
        self,
        root_directory: Path | str,
        serialiser: Optional[Serialiser] = None,
        *,
        max_entries: Optional[int] = None,
        shard_depth: int = DEFAULT_SHARD_DEPTH,
        shard_width: int = DEFAULT_SHARD_WIDTH,
    ) -> None:
        """Initialise the cache in the given root directory.

        - root_directory: Base directory for the cache.
        - serialiser: Object providing dumps/loads; defaults to JSONSerialiser.
        - max_entries: Maximum number of entries to keep; older ones are evicted.
        - shard_depth/width: Directory sharding parameters.
        """
        if shard_depth < 0 or shard_width <= 0:
            raise ValueError("Shard depth must be >= 0 and shard width must be > 0")

        self._root: Path = Path(root_directory)
        self._serialiser: Serialiser = serialiser or JSONSerialiser()
        self._settings: CacheSettings = CacheSettings(
            max_entries=max_entries, shard_depth=shard_depth, shard_width=shard_width
        )

        self._root.mkdir(parents=True, exist_ok=True)
        LOGGER.debug("Initialised DiskCache at %s", self._root)

    def set(self, key: str, value: Any, *, time_to_live_seconds: Optional[float] = None) -> None:
        """Store a value under key with an optional time-to-live in seconds."""
        self._validate_key(key)
        digest = self._digest_key(key)
        directory_path, data_path, metadata_path = self._paths_for_digest(digest)
        directory_path.mkdir(parents=True, exist_ok=True)

        now = time.time()
        expires_at = None if time_to_live_seconds is None else now + float(time_to_live_seconds)
        metadata = {
            "created_at": now,
            "updated_at": now,
            "expires_at": expires_at,
            "digest": digest,
        }

        data_bytes = self._serialiser.dumps(value)
        self._atomic_write_bytes(data_path, data_bytes)
        self._atomic_write_text(metadata_path, json.dumps(metadata, separators=(",", ":"), ensure_ascii=False))

        try:
            self._enforce_capacity()
        except OSError as exc:
            # Capacity enforcement is best-effort; failure should not prevent set().
            LOGGER.warning("Failed to enforce cache capacity: %s", exc)

    def get(self, key: str, default: Any = _MISSING) -> Any:
        """Retrieve a value for key. Returns default or raises CacheKeyError if absent/expired."""
        self._validate_key(key)
        digest = self._digest_key(key)
        _, data_path, metadata_path = self._paths_for_digest(digest)

        try:
            metadata = self._read_metadata(metadata_path)
        except FileNotFoundError:
            if default is _MISSING:
                raise CacheKeyError(key)
            return default
        except CacheCorruptionError:
            self._delete_pair(data_path, metadata_path)
            if default is _MISSING:
                raise CacheKeyError(key)
            return default

        if self._is_expired(metadata):
            self._delete_pair(data_path, metadata_path)
            if default is _MISSING:
                raise CacheKeyError(key)
            return default

        try:
            data = data_path.read_bytes()
        except FileNotFoundError:
            # Inconsistent state: metadata exists but data missing. Clean up.
            LOGGER.warning("Metadata present but data missing for digest %s", digest)
            self._delete_pair(data_path, metadata_path)
            if default is _MISSING:
                raise CacheKeyError(key)
            return default
        except OSError as exc:
            raise CacheError(f"Failed to read cache entry: {exc}") from exc

        return self._serialiser.loads(data)

    def delete(self, key: str) -> bool:
        """Delete an entry by key. Returns has_deleted flag."""
        self._validate_key(key)
        digest = self._digest_key(key)
        _, data_path, metadata_path = self._paths_for_digest(digest)
        return self._delete_pair(data_path, metadata_path)

    def clear(self) -> None:
        """Remove all entries from the cache."""
        if not self._root.exists():
            return
        for child in self._root.iterdir():
            try:
                if child.is_dir():
                    shutil.rmtree(child)
                else:
                    child.unlink(missing_ok=True)
            except OSError as exc:
                raise CacheError(f"Failed to clear cache at {child}") from exc

    def has_key(self, key: str) -> bool:
        """Return True if the given key is present and not expired."""
        try:
            self.get(key)
        except CacheKeyError:
            return False
        return True

    def __contains__(self, key: object) -> bool:
        """Support key in cache semantics."""
        if not isinstance(key, str):
            return False
        return self.has_key(key)

    def size(self) -> int:
        """Return the number of entries currently stored (best-effort)."""
        count = 0
        for data_path in self._iter_data_files():
            digest = data_path.stem
            metadata_path = data_path.with_suffix(META_SUFFIX)
            if not metadata_path.exists():
                continue
            try:
                metadata = self._read_metadata(metadata_path)
            except CacheCorruptionError:
                self._delete_pair(data_path, metadata_path)
                continue
            if self._is_expired(metadata):
                self._delete_pair(data_path, metadata_path)
                continue
            count += 1
        return count

    def vacuum(self) -> int:
        """Remove expired or corrupt entries. Returns number of entries removed."""
        removed = 0
        for data_path in self._iter_data_files():
            metadata_path = data_path.with_suffix(META_SUFFIX)
            try:
                metadata = self._read_metadata(metadata_path)
            except (FileNotFoundError, CacheCorruptionError):
                if self._delete_pair(data_path, metadata_path):
                    removed += 1
                continue
            if self._is_expired(metadata) and self._delete_pair(data_path, metadata_path):
                removed += 1
        return removed

    # Helpers

    def _validate_key(self, key: str) -> None:
        """Validate key preconditions to avoid undefined behaviour."""
        if not isinstance(key, str):
            raise TypeError("Key must be a string")
        if not key:
            raise ValueError("Key must be a non-empty string")

    def _digest_key(self, key: str) -> str:
        """Compute a stable hex digest for the key."""
        # Non-obvious choice: a cryptographic hash avoids collisions deterministically
        # without having to store the original key on disk.
        return hashlib.sha256(key.encode("utf-8")).hexdigest()

    def _paths_for_digest(self, digest: str) -> Tuple[Path, Path, Path]:
        """Return directory, data path, and metadata path for a digest."""
        parts = self._shard_parts(digest)
        directory_path = self._root.joinpath(*parts) if parts else self._root
        data_path = directory_path / f"{digest}{DATA_SUFFIX}"
        metadata_path = directory_path / f"{digest}{META_SUFFIX}"
        return directory_path, data_path, metadata_path

    def _shard_parts(self, digest: str) -> Tuple[str, ...]:
        """Compute directory shard parts for the digest to limit directory fan-out."""
        depth = self._settings.shard_depth
        width = self._settings.shard_width
        if depth == 0:
            return ()
        parts: list[str] = []
        start = 0
        for _ in range(depth):
            end = start + width
            parts.append(digest[start:end])
            start = end
        return tuple(parts)

    def _atomic_write_bytes(self, target_path: Path, data: bytes) -> None:
        """Write bytes atomically by writing to a temporary then replacing."""
        temp_path = target_path.with_name(f".{target_path.name}.{uuid.uuid4().hex}.tmp")
        try:
            temp_path.write_bytes(data)
            temp_path.replace(target_path)
        except OSError as exc:
            # Attempt cleanup of temp file; ignore failure.
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass
            raise CacheWriteError(f"Failed to write data file: {exc}") from exc

    def _atomic_write_text(self, target_path: Path, text: str) -> None:
        """Write text atomically by writing to a temporary then replacing."""
        temp_path = target_path.with_name(f".{target_path.name}.{uuid.uuid4().hex}.tmp")
        try:
            with temp_path.open("w", encoding="utf-8") as handle:
                handle.write(text)
            temp_path.replace(target_path)
        except OSError as exc:
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass
            raise CacheWriteError(f"Failed to write metadata file: {exc}") from exc

    def _read_metadata(self, metadata_path: Path) -> dict:
        """Read and parse metadata JSON, raising on corruption."""
        try:
            with metadata_path.open("r", encoding="utf-8") as handle:
                return json.load(handle)
        except FileNotFoundError:
            raise
        except (OSError, json.JSONDecodeError, UnicodeDecodeError) as exc:
            raise CacheCorruptionError(f"Metadata is unreadable: {exc}") from exc

    def _is_expired(self, metadata: dict) -> bool:
        """Return is_expired indicating whether the entry has passed its expiry time."""
        expires_at = metadata.get("expires_at")
        if expires_at is None:
            return False
        return time.time() >= float(expires_at)

    def _delete_pair(self, data_path: Path, metadata_path: Path) -> bool:
        """Delete both data and metadata files if present. Returns has_deleted."""
        has_deleted = False
        try:
            data_path.unlink(missing_ok=True)
            has_deleted = True
        except OSError as exc:
            raise CacheError(f"Failed to delete data file: {exc}") from exc
        try:
            metadata_path.unlink(missing_ok=True)
            has_deleted = True
        except OSError as exc:
            raise CacheError(f"Failed to delete metadata file: {exc}") from exc
        return has_deleted

    def _enforce_capacity(self) -> None:
        """Ensure entry count does not exceed capacity by removing oldest entries."""
        max_entries = self._settings.max_entries
        if max_entries is None or max_entries < 0:
            return

        entries: list[tuple[float, Path]] = []
        for data_path in self._iter_data_files():
            try:
                mtime = data_path.stat().st_mtime
            except OSError:
                # If we cannot stat, consider it stale and schedule for removal first.
                mtime = -1.0
            entries.append((mtime, data_path))

        if len(entries) <= max_entries:
            return

        # Sort by most recent first, keep the latest, remove the rest.
        entries.sort(key=lambda t: t[0], reverse=True)
        to_remove = entries[max_entries:]

        for _, data_path in to_remove:
            metadata_path = data_path.with_suffix(META_SUFFIX)
            self._delete_pair(data_path, metadata_path)

    def _iter_data_files(self) -> tuple[Path, ...]:
        """Return a tuple of all data file Paths in the cache."""
        # Immutable return (tuple) to align with preference for immutability.
        files: list[Path] = []
        if not self._root.exists():
            return tuple()
        for directory_path in self._iter_directories_preorder(self._root):
            for child in directory_path.iterdir():
                if child.is_file() and child.name.endswith(DATA_SUFFIX):
                    files.append(child)
        return tuple(files)

    def _iter_directories_preorder(self, start: Path) -> tuple[Path, ...]:
        """Return a tuple of directories in preorder starting from start."""
        # Non-obvious choice: explicit stack to avoid recursion depth limits.
        result: list[Path] = []
        stack: list[Path] = [start]
        while stack:
            directory_path = stack.pop()
            if not directory_path.is_dir():
                continue
            result.append(directory_path)
            # Reverse-sort ensures stable left-to-right traversal order.
            subdirectories = sorted((p for p in directory_path.iterdir() if p.is_dir()), reverse=True)
            stack.extend(subdirectories)
        return tuple(result)
